def safe_extract(archive, target):
    root = os.path.realpath(target) + os.sep
    for member in archive.getmembers():
        dest = os.path.realpath(os.path.join(target, member.name))
        if not dest.startswith(root):
            raise ValueError("unsafe archive member: " + member.name)
    archive.extractall(target)


def one_file(root, suffix, contains=None):
    hits = []
    for base, _, files in os.walk(root):
        for name in files:
            low = name.lower()
            if low.endswith(suffix) and (contains is None or contains in low):
                hits.append(os.path.join(base, name))
    if len(hits) != 1:
        raise ValueError(f"expected one file matching {contains or '*'}{suffix}; found {hits}")
    return hits[0]


